using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class BanditEncounterTests
{
 static readonly EntityId Site=new("site:castle");
 internal static WorldSession Start(){var setup=NewGameWorldTests.Setup([NewGameWorldTests.Officer("created:bandit-player",StartTemplate.Retainer,lord:"person:nobunaga")]);return new(NewGameWorld.Create(setup.World,setup.Registered,"created:bandit-player",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy,developmentPolicy:CharacterDevelopment.Policy,banditPolicy:BanditEncounter.Policy));}
 static BanditInput Input(WorldSession s,BanditAction action)=>new(new("request:bandit/"+s.Revision),action,Site);
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 [Fact]public void ContactStopsMovementAndPaymentMovesActualMoneyOnce(){var s=Start();var move=TravelWorld.Move(s.DiagnosticSnapshot(),"request:bandit-move","sakai");Assert.Equal(ResultCode.NotAvailable,s.Submit(move,s.Revision).Code);Assert.NotNull(BanditEncounter.Current(s.DiagnosticSnapshot()));Assert.True(s.Paused);long cash=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);var pay=Input(s,BanditAction.Pay);Good(s.ManageBandits(pay,s.Revision));Assert.Equal(cash-20,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(20,BanditEncounter.BanditMoney(s.DiagnosticSnapshot(),Site));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageBandits(pay,s.Revision).Code);Good(s.Submit(move,s.Revision));}
 [Fact]public void ContactCombatAndMidSaveRetainSameInjuries(){var s=Start();Good(s.ManageBandits(Input(s,BanditAction.Encounter),s.Revision));Good(s.ManageBandits(Input(s,BanditAction.Fight),s.Revision));NewGameWorldTests.At(s,5);s.SetPaused(true);var original=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"bandit-save-"+Guid.NewGuid().ToString("N")),original.Definitions);store.Save(s,"manual",original.WorldId);var host=new WorldSessionHost(new WorldSession(original));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("manual"),host.Current,host.Current.Revision));var restored=host.Current;foreach(var x in new[]{s,restored})NewGameWorldTests.At(x,30);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));Assert.True(BanditEncounter.Injury(s.DiagnosticSnapshot(),s.PlayerControl)>0);Assert.Null(BanditEncounter.Current(s.DiagnosticSnapshot()));}
 [Fact]public void ForgedHealthIsRejected(){var s=Start();Good(s.ManageBandits(Input(s,BanditAction.Encounter),s.Revision));var w=s.DiagnosticSnapshot();var e=w.Bandits!.Encounters[0];w.Bandits=w.Bandits with{Encounters=[e with{People=e.People.Select(p=>p.Side==0?p with{Health=1}:p).ToArray()}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void WithdrawDoesNotCreatePaymentOrDamage(){var s=Start();Good(s.ManageBandits(Input(s,BanditAction.Encounter),s.Revision));Good(s.ManageBandits(Input(s,BanditAction.Withdraw),s.Revision));Assert.Equal(0,BanditEncounter.Injury(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(0,BanditEncounter.BanditMoney(s.DiagnosticSnapshot(),Site));}
 [Fact]public void EscortMovesBothPeopleAndPaysOnlyAfterArrival(){var s=Start();Good(s.ManageBandits(Input(s,BanditAction.Encounter),s.Revision));Good(s.ManageBandits(Input(s,BanditAction.Pay),s.Revision));var issuer=GuardJobs.Issuers(s.DiagnosticSnapshot()).First();var dest=GuardJobs.Destinations(s.DiagnosticSnapshot(),Site).First();var accept=new GuardInput(new("request:escort"),GuardAction.Accept,Issuer:issuer,Destination:dest);long worker=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl),money=NewGameWork.Balance(s.DiagnosticSnapshot(),issuer);Good(s.ManageGuard(accept,s.Revision));Assert.Equal(money-80,NewGameWork.Balance(s.DiagnosticSnapshot(),issuer));var settle=new GuardInput(new("request:escort-settle"),GuardAction.Settle,accept.Id);Assert.Equal(ResultCode.NotAvailable,s.ManageGuard(settle,s.Revision).Code);Good(s.ManageGuard(new(new("request:escort-depart"),GuardAction.Depart,accept.Id),s.Revision));NewGameWorldTests.At(s,2);var restored=new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(s.DiagnosticSnapshot())));long end=s.DiagnosticSnapshot().Branches!.Journeys.Max(j=>j.Legs[^1].EndAt)+2;foreach(var session in new[]{s,restored}){NewGameWorldTests.At(session,end);Good(session.ManageGuard(settle,session.Revision));}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));Assert.Equal(worker+80,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageGuard(settle,s.Revision).Code);}
 [Fact]public void GuardCancellationReturnsEscrowAndNoSuppressionRewardWithoutVictory(){var s=Start();var issuer=GuardJobs.Issuers(s.DiagnosticSnapshot()).First();long money=NewGameWork.Balance(s.DiagnosticSnapshot(),issuer);var accept=new GuardInput(new("request:suppression"),GuardAction.Accept,Issuer:issuer,Kind:GuardKind.Suppression);Good(s.ManageGuard(accept,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.ManageGuard(new(new("request:unearned"),GuardAction.Settle,accept.Id),s.Revision).Code);Good(s.ManageGuard(new(new("request:cancel"),GuardAction.Cancel,accept.Id),s.Revision));Assert.Equal(money,NewGameWork.Balance(s.DiagnosticSnapshot(),issuer));}
 [Fact]public void ConsentingCompanionsDefeatGangAndEarnSuppressionEscrow(){var records=new[]{NewGameWorldTests.Officer("created:leader"),NewGameWorldTests.Officer("created:one",StartTemplate.Retainer,lord:"created:leader"),NewGameWorldTests.Officer("created:two",StartTemplate.Retainer,lord:"created:leader")}.Select(p=>p with{Attributes=new(100,100,40,40)}).ToArray();var setup=NewGameWorldTests.Setup(records);var s=new WorldSession(NewGameWorld.Create(setup.World,setup.Registered,"created:leader",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy,developmentPolicy:CharacterDevelopment.Policy,companionPolicy:PersonalCompanions.Policy,banditPolicy:BanditEncounter.Policy));foreach(var person in new[]{"created:one","created:two"})Good(s.ManageCompanion(new(new("request:join/"+person.Replace(':','/')),new(person),CompanionAction.Agree,20),s.PlayerControl,s.Revision));var accept=new GuardInput(new("request:defeat-job"),GuardAction.Accept,Issuer:new("person:nobunaga"),Kind:GuardKind.Suppression);Good(s.ManageGuard(accept,s.Revision));Good(s.ManageBandits(Input(s,BanditAction.Encounter),s.Revision));Good(s.ManageBandits(Input(s,BanditAction.Fight),s.Revision));NewGameWorldTests.At(s,100);Assert.False(BanditEncounter.Dangerous(s.DiagnosticSnapshot(),Site));long cash=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);Good(s.ManageGuard(new(new("request:defeat-settle"),GuardAction.Settle,accept.Id),s.Revision));Assert.Equal(cash+80,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ResultCode.NotAvailable,s.ManageBandits(Input(s,BanditAction.Encounter),s.Revision).Code);}
}
